def compute(vars):
    doubtful_receivables = -vars["v1"]
    trade_receivables = vars["v2"]

    if trade_receivables == 0:
        return None

    ratio = doubtful_receivables / trade_receivables
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "doubtful_receivables": doubtful_receivables,
            "trade_receivables": trade_receivables,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
